    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public payable {
        // No extra precondition: test for any caller (msg.sender of this run)
        bool reverted; try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
