import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public { 
        // deployer will be the default test address (address(this) isn't used for calls to c)
        deployer = address(this);
        c = new C();
    }

    // Fuzzed params: receiver address and amount. The distinguishing input is when the caller is the owner (deployer).
    function testFuzz_property(address receiver, uint256 amount) public {
        // keep receiver wide but avoid zero address for admissible domain check here is optional;
        // we'll still allow zero to be passed to observe that both contracts require receiver != address(0),
        // but we must ensure amount fits within contract balance when called by owner: fund the contract.

        // Fund the contract so transfers can succeed for positive amounts
        // Bound amount to a reasonable size so vm.deal can fund the caller and transfer can succeed
        uint256 bounded = bound(amount, 0, 1 ether);
        vm.deal(address(this), 1 ether);

        // The property: in the correct contract, the deployer (owner) is always permitted to call sendTo
        // (subject to receiver != 0 and amount > 0). We test the general rule by calling as the owner (deployer).
        bool ok;
        // ensure call is made as the owner = deployer
        // send value is not required (transfer uses contract balance), so just call normally
        try c.sendTo(receiver, bounded) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: for the reference contract, when called by the owner (deployer),
        // the call should succeed whenever receiver != address(0) and amount > 0 and contract has enough balance.
        // We ensure preconditions: require amount > 0 and receiver != 0 and fund contract with amount.

        // If preconditions are not met, the reference also reverts; we only assert when preconditions hold.
        if (receiver != address(0) && bounded > 0) {
            // ensure contract has the funds to transfer
            // fund contract by sending bounded ETH from deployer
            // (we already vm.deal deployer with 1 ether above)
            (bool sent, ) = address(c).call{value: bounded}('');
            require(sent, "funding failed");

            // Now call again as owner and observe
            try c.sendTo(receiver, bounded) {
                ok = true;
            } catch {
                ok = false;
            }

            // In the reference contract the owner is allowed, so ok must be true for all such inputs.
            assertTrue(ok);
        }
    }
}

