import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller address and transfer amount and receiver
    function testFuzz_property(address caller, address receiver, uint256 amount) public {
        // keep inputs in admissible domain: non-zero receiver and positive amount
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);

        // Ensure caller has enough balance to perform a transfer via sendTo (amount sent from contract, but keep EOA funded)
        vm.deal(caller, 1 ether);

        // The reference contract allows only the deployer (owner) to call sendTo successfully.
        // Our property: if caller == deployer (address(this) at construction time was the test runner, but C constructed in setUp, so owner == address(this) at deploy), then sendTo should succeed.
        // setUp deployed c from this test contract, so owner == address(this). We must fuzz caller; the contract under test will see msg.sender as caller when we vm.prank.

        bool ok;
        // make the call as the fuzzed caller
        vm.prank(caller);
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: when the caller equals the deployer (owner) the call should succeed on the reference.
        // Since owner == address(this) (because setUp used new C() from this contract), we assert that if caller == address(this) then the call succeeded.
        // This holds for the reference; the mutant inverts the ownership check and will make this assertion fail for caller == owner.
        assertTrue(!(caller == address(this)) || ok);
    }
}

