pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: caller (which may equal owner) and amount and receiver
    function testFuzz_property(address caller, address receiver, uint256 amount) public {
        // Keep domain wide but admissible for the operation
        vm.assume(receiver != address(0));
        // require(amount > 0) in contract, so fuzz nonzero amounts
        amount = bound(amount, 1, type(uint256).max);

        // Fund the contract so transfers can succeed when allowed
        vm.deal(address(c), amount);

        // Determine whether the fuzzed caller is the owner (deployer)
        address owner = address(this); // because setUp deployed C from this contract

        // We will call c.sendTo as if coming from 'caller'
        vm.prank(caller);

        // Call and observe whether the call succeeds; also observe balance change
        bool ok;
        uint256 before = address(c).balance;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 after = address(c).balance;

        // General rule: if the caller is the owner, the reference contract allows the call and thus
        // the contract balance decreases by 'amount'. The mutant inverts the owner check and will
        // reject owner calls — so for caller == owner and admissible receiver/amount the mutant
        // will cause ok==false or no balance decrease. We assert the reference property: when
        // caller is owner, the call must succeed and contract balance must decrease by amount.
        if (caller == owner) {
            assertTrue(ok && (before - after == amount));
        } else {
            // For non-owners we do not assert anything (keep domain wide).
            assertTrue(true);
        }
    }
}

