        // ensure this tester has enough balance if transfer were attempted
        // (the test does not send Ether to c; we only observe c.balance)

        // Observe c balance before the call
        uint before = address(c).balance;

        // Make the deciding call: owner must call sendTo, so this contract must be the owner.
        // The original contract C sets owner to the deployer; the test harness should construct C with this contract as owner.
        // We call sendTo which in the mutant may allow sending to address(0).
        // This is a state-changing call and must be a top-level statement.
        c.sendTo(receiver, amount);

        // Observe c balance after the call
        uint after = address(c).balance;

        // General rule: if receiver is the zero address then c's balance does not decrease (P enforces this by rejecting zero receiver)
        // For all inputs this must hold on P, but will be violated by M which permits transfer to zero.
        assert(!(receiver == address(0)) || after >= before);
    }

    // allow receiving Ether if needed by the test environment
    receive() external payable {}
}

